      "pins": ["FCC2.11", "FCC2.27", "FCC2.50", "FCC2.75", "FCC2.100", "NAVC2.19", "NAVC2.32", "NAVC2.48", "NAVC2.64"],
      "nets": ["unconnected-(FCC2-VDD-Pad11)", "unconnected-(FCC2-VDD-Pad27)", "unconnected-(FCC2-VDD-Pad50)", "unconnected-(FCC2-VDD-Pad75)", "unconnected-(FCC2-VDD-Pad100)", "unconnected-(NAVC2-VDD-Pad19)", "unconnected-(NAVC2-VDD-Pad32)", "unconnected-(NAVC2-VDD-Pad48)", "unconnected-(NAVC2-VDD-Pad64)"],
      "observed": "The netlist shows all VDD pins of FCC2 (STM32H753) and NAVC2 (STM32F405) on unconnected nets, not on any 3.3V rail.",
      "expected": "The specification states the 3.3 V LDO produces 3V3 for MCUs and sensors; all MCU VDD pins must be connected to the 3.3V rail.",
      "evidence": [
        {"source": "netlist", "quote": "(net (code \"216\") (name \"unconnected-(FCC2-VDD-Pad11)\") (class \"Default\") (node (ref \"FCC2\") (pin \"11\") (pinfunction \"VDD\") (pintype \"power_in\")))"},
        {"source": "spec", "quote": "3.3 V LDO (MCUs + sensors) ... produces 3V3 for \"MCUs and Sensors\""}
      ],
      "impact": "Both microcontrollers receive no power, so the board cannot boot or function at all.",
      "confidence": 1.0
    },
    {
      "category": "bridged_nets",
      "components": ["FCC2", "UART3_FCC2"],
      "pins": ["FCC2.48", "FCC2.73", "UART3_FCC2.3", "UART3_FCC2.4"],
      "nets": ["NET0082", "NET0116"],
      "observed": "FCC2 VCAP pins 48 and 73 are connected to UART3_FCC2 pins 3 and 4 on nets NET0082 and NET0116, with no decoupling capacitors to ground.",
      "expected": "VCAP pins are internal regulator outputs requiring 2.2uF decoupling capacitors to GND; the UART3 connector should carry UART TX/RX signals, not VCAP.",
      "evidence": [
        {"source": "netlist", "quote": "(net (code \"52\") (name \"NET0082\") (class \"Default\") (node (ref \"FCC2\") (pin \"48\") (pinfunction \"VCAP\") (pintype \"power_out\")) (node (ref \"UART3_FCC2\") (pin \"3\") (pinfunction \"Pin_3\") (pintype \"passive\")))"},
        {"source": "spec", "quote": "programming/debug via SWD, USB DFU, and UART-to-USB"}
      ],
      "impact": "The STM32H7 internal regulator is not properly decoupled and is exposed on a connector, likely preventing the MCU from running and making the UART3 interface nonfunctional.",
      "confidence": 1.0
    },
    {
      "category": "other",
      "components": ["U6"],
      "pins": ["U6.1"],
      "nets": ["+3.3V"],
      "observed": "PCA9685PW U6 pin 1 (A0) is tied to +3.3V, which sets the I2C address to 0x41.",
      "expected": "The specification states the PCA9685PW I2C address is 0x40, which requires A0 to be tied to GND.",
      "evidence": [
        {"source": "netlist", "quote": "(node (ref \"U6\") (pin \"1\") (pinfunction \"A0\") (pintype \"input\")) on net +3.3V"},
        {"source": "spec", "quote": "PWM/servo driver | FCCPeripherals | NXP PCA9685PW (I2C 16-ch PWM), I2C addr 0x40"}
      ],
      "impact": "The PWM driver responds at 0x41 instead of 0x40, so servo control will fail unless the firmware is changed to use the wrong address.",
      "confidence": 0.95
    }
  ],
  "summary": "The design files contain multiple severe anomalies: both MCU VDD pins are unconnected, FCC2 VCAP pins are miswired to a UART connector instead of decoupling capacitors, and the PCA9685 address pin is tied high, changing its I2C address from the specified 0x40 to 0x41."
}

